import type { Elements, RenderElement } from 'claude-code'

import type { Tab } from '../types'
import { wordmarkArt } from './art'
import { card } from './kit'
import type { Head } from './state'

export const PANE = 'fishstack'
export const PANE_TITLE = 'fishStack'
// How wide the pane asks to dock: a sidebar, as the desktop's own panel is.
export const PANE_COLUMNS = 46

// The elements the pane draws with, so it draws on every surface: mobile has
// no Input or Select, the terminal no Svg, and the tabs leave those out where
// they are missing.
export type Ui = Pick<Elements['terminal'], 'Box' | 'Text' | 'Button' | 'Markdown' | 'Code'> &
  Partial<Pick<Elements['terminal'], 'Input' | 'Select'>> &
  Partial<Pick<Elements['desktop'], 'Svg' | 'Client'>>

// $.ui.resolve completes every table with stand-ins that draw nothing; this
// leaves out what the surface lacks, so the tabs can test for it: the
// terminal draws no Svg, mobile no Input or Select. A Client that failed
// (ui.fault) leaves them all out until a reload, the Buttons standing in.
export function resolveUi(table: Ui, surface: string, isClientDown: boolean): Ui {
  return {
    ...table,
    Svg: surface === 'terminal' ? undefined : table.Svg,
    // Drawn controls take presses through a Client, which only the desktop
    // lays over a picture; the terminal keeps its Buttons.
    Client: surface === 'desktop' && !isClientDown ? table.Client : undefined,
    Input: surface === 'mobile' ? undefined : table.Input,
    Select: surface === 'mobile' ? undefined : table.Select,
  }
}

export const TABS: { id: Tab; label: string; icon: string }[] = [
  { id: 'worktree', label: 'Worktree', icon: '⎇' },
  { id: 'dials', label: 'Dials', icon: '◇' },
  { id: 'context', label: 'Context', icon: '▤' },
]

export function isTab(value: string): value is Tab {
  return TABS.some(one => one.id === value)
}

// One card: its head names it on the left and says its state on the right,
// a press opens or closes it, and while open its body sits under the head.
export function cardOf(ui: Ui, id: Tab, isOpen: boolean, head: Head, onToggle: () => void, body: RenderElement | null) {
  const { Box, Button, Text } = ui
  const index = TABS.findIndex(one => one.id === id)
  const one = TABS[index]!
  return card(
    ui,
    `card-${id}`,
    [
      <Box key={`head-${id}`} justifyContent="space-between" alignItems="center" gap={1}>
        <Button key={`tab-${id}`} plain hotkey={String(index + 1)} onPress={onToggle}>
          <Text color="suggestion">{one.icon} </Text>
          <Text bold>{one.label}</Text>
        </Button>
        <Button key={`tab-${id}-state`} plain onPress={onToggle}>
          <Text color={head.tone} dimColor={head.tone === undefined}>
            {head.value}
          </Text>
          <Text dimColor> {isOpen ? '⌄' : '›'}</Text>
        </Button>
      </Box>,
      isOpen && body !== null && (
        <Box key={`body-${id}`} flexDirection="column" gap={1} marginTop={1}>
          {body}
        </Box>
      ),
    ],
    { tone: isOpen ? 'selected' : 'plain' },
  )
}

// The pane is one column of cards, as the desktop's own side panel is, one
// open at a time. Each tab's file draws the whole pane while its card is
// open; pane.tsx draws it with every card closed.
export function frame(ui: Ui, current: Tab | null, columns: number, onSelect: (id: Tab | null) => void, body: RenderElement | null, heads: Record<Tab, Head>) {
  const { Box, Svg } = ui
  const rich = Svg !== undefined
  return (
    <Box flexDirection="column" width={columns} gap={rich ? 1 : 0}>
      {rich && (
        <Box key="pane-head">
          <Svg source={wordmarkArt().source} alt="fishStack" width={wordmarkArt().width} height={wordmarkArt().height} />
        </Box>
      )}
      {TABS.map(one => cardOf(ui, one.id, one.id === current, heads[one.id], () => onSelect(one.id === current ? null : one.id), one.id === current ? body : null))}
    </Box>
  )
}

// How wide a card opened from the rail is drawn above the prompt: room for
// its rows, never the whole width of a wide window.
export const BAND_CARD_COLUMNS = 72

// How wide each card of a grid is, so the cards fill the row: as many as fit
// at `least` columns each, with one column between them.
export function gridWidth(columns: number, least: number): number {
  const perRow = Math.max(1, Math.floor((columns + 1) / (least + 1)))
  return Math.floor((columns - (perRow - 1)) / perRow)
}

export function bar(fraction: number, width: number): string {
  const filled = Math.round(Math.min(1, Math.max(0, fraction)) * width)
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

export function tokens(count: number): string {
  if (count >= 1_000_000) return `${(count / 1_000_000).toFixed(1)}M`
  if (count >= 1_000) return `${(count / 1_000).toFixed(count >= 10_000 ? 0 : 1)}k`
  return String(count)
}

files.hooks/enforce.ts:
// The dials enforced in code, not only asked for in the prompt. Only rules a
// hook can check without guessing, and each built so it can never trap a
// session: a check that fails lets the call through, a refused edit is
// refused twice at most, and the end of a turn is held back once at most.
//
// The facts are kept as the turn happens (turn.start resets them; guard.ts
// records each tool call and the text the agent streams), never parsed back
// from the transcript.
import type { DialKey, DialValues } from '../types'

export type TurnFacts = {
  // What the main agent has written this turn, as it streamed: a spec
  // written in the same response as the edit counts before that edit runs,
  // which the transcript, written once the response ends, cannot show.
  said: string
  // Files or the working tree changed: Edit, Write and the like, a shell
  // command that is not a known read, by the agent or a subagent.
  changes: number
  // Of those, how many touched more than docs.
  codeChanges: number
  // The order calls ran in, so a check can be told apart from one that ran
  // before the last change.
  seq: number
  lastChange: number
  lastCheck: number
  // Subagents the main agent started this turn.
  agents: number
  // A plan the agent made with a tool: TodoWrite, or ExitPlanMode's plan.
  isPlanned: boolean
  // How many edits Foresight has refused this turn.
  foresightRefusals: number
}

export function freshTurn(): TurnFacts {
  return { said: '', changes: 0, codeChanges: 0, seq: 0, lastChange: 0, lastCheck: 0, agents: 0, isPlanned: false, foresightRefusals: 0 }
}

// The turn under way in this process; null outside one.
let facts: TurnFacts = freshTurn()

export function beginTurn(): void {
  facts = freshTurn()
}

export function turnFacts(): TurnFacts {
  return facts
}

export const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
export const SUBAGENT_TOOLS = new Set(['Agent', 'Task'])
// Foresight never refuses more often than this in one turn: past it, the
// agent edits whatever it wrote first.
export const MAX_FORESIGHT_REFUSALS = 2

// Tests, builds, typechecks and linters by their usual names.
const CHECK = /(^|[\s;&|(])(npm|pnpm|yarn|bun)\s+(run\s+)?(test|build|lint|typecheck|check)\b|\b(jest|vitest|pytest|mocha|rspec|phpunit|tsc|eslint|ruff|mypy|pyright|swiftlint|xcodebuild|gradle|mvn)\b|\bgo\s+(test|build|vet)\b|\bcargo\s+(test|build|check|clippy)\b|\bswift\s+(build|test)\b|\bmake\b|\bplugin\s+(test|validate)\b|\be2e\b/

export function isCheckCommand(command: string): boolean {
  return CHECK.test(command)
}

// A shell command that plainly writes a file: a redirect into one (not
// /dev/null, not 2>&1), an in-place edit, or a copy, move, touch or tee.
// Anything else, git and npm included, is not counted as a change: a
// command merely not known to be a read must never hold a turn back.
const SHELL_WRITE = /(^|[^0-9&>])>{1,2}\s*(?!\/dev\/null|&)[^\s|;&]|\bsed\s+(-[a-zA-Z]*\s+)*-i\b|\bperl\s+-[a-z]*i|\btee\b|(^|[\s;&|(])(cp|mv|touch|install)\s/

export function isShellWrite(command: string): boolean {
  return SHELL_WRITE.test(command)
}

const DOC = /\.(md|mdx|txt|rst|adoc|png|jpe?g|gif|svg)$/i

export function isDocPath(path: string): boolean {
  return DOC.test(path)
}

// A change, as guard.ts sees each call go through.
export function noteChange(path: string | null): void {
  facts.seq++
  facts.changes++
  if (path === null || !isDocPath(path)) facts.codeChanges++
  facts.lastChange = facts.seq
}

export function noteCheck(): void {
  facts.seq++
  facts.lastCheck = facts.seq
}

export function noteAgent(): void {
  facts.agents++
}

export function notePlan(): void {
  facts.isPlanned = true
}

// A piece of the main agent's visible text, as guard.ts sees it stream.
export function noteSaid(text: string): void {
  facts.said += text
}

// What Foresight's spec levels look for in what the agent wrote this turn.
export function hasSpec(level: number, texts: string[]): boolean {
  const said = texts.join('\n')
  if (!/acceptance criteria/i.test(said)) return false
  if (level < 5) return true
  return ['problem', 'approach', 'alternatives'].every(heading => new RegExp(`(^|\\n)\\s*(#+\\s*|\\*\\*)?${heading}`, 'i').test(said))
}

// Foresight 4 and 5: the turn's first edit waits for a spec, once or twice.
// Levels 1 to 3 are left to the prompt: a plan of steps is too loose a thing
// to hold an edit back for.
export function foresightRefusal(level: number): string | null {
  if (level < 4 || facts.isPlanned || facts.changes > 0) return null
  if (facts.foresightRefusals >= MAX_FORESIGHT_REFUSALS) return null
  if (hasSpec(level, [facts.said])) return null
  facts.foresightRefusals++
  return level === 5
    ? 'fishStack dials, Foresight is Deep spec: before the first edit, post the spec as a message with the headings Problem, Constraints, Approach, Alternatives considered, Edge cases, Risks, Files, Acceptance criteria. Then edit.'
    : 'fishStack dials, Foresight is Write a spec: before the first edit, post a short spec as a message: the problem, your approach, the files involved and a list headed Acceptance criteria. Then edit.'
}

// Crew 1 and 2: no subagent, or one.
export function crewRefusal(level: number): string | null {
  if (level === 1) return 'Crew is set to Solo in fishStack: do the work yourself without subagents.'
  if (level === 2 && facts.agents >= 1) return 'fishStack dials, Crew is Scouts: one scout per request, and it has been sent. Do the rest yourself.'
  return null
}

const VOICE_PARTS: Record<number, string[]> = {
  4: ['What changed', 'Why this way', 'What I verified', 'What I left out'],
  5: ['How it worked before', 'What I changed and why', 'Alternatives I considered', 'What I learned about this codebase', 'What to know next time'],
}

// What a turn that changed code still owes before it ends, in one message:
// null when nothing, or when the turn is already one Stop hook held back.
export function stopReason(values: DialValues, lastMessage: string, isHeldBack: boolean): string | null {
  if (isHeldBack || facts.codeChanges === 0) return null
  const owed: string[] = []
  if (values.proof >= 2 && facts.lastCheck < facts.lastChange) {
    owed.push(values.proof === 2 ? 'build or typecheck what you changed' : 'run the tests (or the build) for what you changed')
  }
  if (values.tenacity === 4 && !/checklist/i.test(lastMessage)) owed.push('end with your Checklist, each line with its status')
  if (values.tenacity === 5 && !/acceptance criteria/i.test(lastMessage)) owed.push('end with your Acceptance criteria, each with the evidence that verifies it')
  const parts = VOICE_PARTS[values.voice]
  if (parts !== undefined) {
    const missing = parts.filter(part => !lastMessage.toLowerCase().includes(part.toLowerCase()))
    if (missing.length > 0) owed.push(`include the labelled parts ${missing.join(', ')}`)
  }
  if (owed.length === 0) return null
  return `fishStack dials, before you finish: ${owed.join('; ')}. Then end your turn as usual. (This is asked once.)`
}

// What a dial's level enforces, for its card; null when it is prompt-only.
export function enforcedRule(key: DialKey, level: number): string | null {
  switch (key) {
    case 'foresight':
      return level >= 4 ? `The first edit of a request waits for ${level === 5 ? 'the deep spec' : 'a spec with Acceptance criteria'} (asked twice at most).` : null
    case 'crew':
      return level === 1 ? 'Subagents are refused.' : level === 2 ? 'One subagent per request; more are refused.' : null
    case 'tenacity':
      return level >= 4 ? `A request that changed code ends with its ${level === 5 ? 'Acceptance criteria' : 'Checklist'} (held back once if not).` : null
    case 'autonomy':
      return level === 5 ? 'A question nobody answers is answered with its recommended option after the wait.' : null
    case 'proof':
      return level >= 2 ? `A request that changed code runs ${level === 2 ? 'a build or typecheck' : 'its tests'} after the last change (held back once if not).` : null
    case 'voice':
      return level >= 4 ? 'A request that changed code ends with the labelled parts (held back once if not).' : null
  }
}

files.hooks/radar-drag.tsx:
// The surface module laid over the Dials radar: press a dial's dot (or
// anywhere along its spoke) and drag it in or out to set its level, as on
// CommissionAI's Dials page; arrow keys move the focus between dials and the
// level up or down. It draws nothing of its own (the radar is the Svg beneath)
// and posts { dial, level } to the hooks module, which validates it.
import type { ClientModule, ClientPointerEvent } from 'claude-code'

type Props = { levels: number[]; width: number; height: number; radius: number }
type State = { axis: number | null; focus: number }

function angleOf(index: number, count: number): number {
  return ((-90 + (index * 360) / count) * Math.PI) / 180
}

// The handlers are set once, on the first call; they read the props of the
// latest one, so a drag compares against the levels drawn now.
let latest: Props = { levels: [], width: 1, height: 1, radius: 1 }

const RadarDrag: ClientModule<Props, State> = (next, surface) => {
  latest = next
  const props = new Proxy({} as Props, { get: (_, key) => latest[key as keyof Props] })
  const { Box } = surface.elements
  const count = props.levels.length

  // Where a pointer event lands, in the radar's own pixels.
  const point = (event: ClientPointerEvent) => {
    const columns = Math.max(1, surface.columns)
    const rows = Math.max(1, surface.rows)
    return {
      x: (((event.fine?.x ?? event.x + 0.5) / columns) * props.width) - props.width / 2,
      y: (((event.fine?.y ?? event.y + 0.5) / rows) * props.height) - props.height / 2,
    }
  }

  const nearestAxis = (x: number, y: number) => {
    const pointer = Math.atan2(y, x)
    let best = 0
    let gap = Infinity
    for (let index = 0; index < count; index++) {
      const delta = Math.abs(Math.atan2(Math.sin(pointer - angleOf(index, count)), Math.cos(pointer - angleOf(index, count))))
      if (delta < gap) {
        gap = delta
        best = index
      }
    }
    return best
  }

  const levelAlong = (axis: number, x: number, y: number) => {
    const angle = angleOf(axis, count)
    const along = x * Math.cos(angle) + y * Math.sin(angle)
    return Math.min(5, Math.max(1, Math.round((along / props.radius) * 5)))
  }

  // One post per frame reaches the hooks module (a later one replaces it), so
  // a press says which dial it selects and its level together.
  const post = (dial: number, level: number, isSelecting = false) => {
    if (isSelecting) surface.post({ select: dial, dial, level })
    else if (props.levels[dial] !== level) surface.post({ dial, level })
  }

  if (surface.state === undefined) {
    surface.setState({ axis: null, focus: 0 })
    surface.onPointer(event => {
      const state = surface.state ?? { axis: null, focus: 0 }
      const { x, y } = point(event)
      if (event.type === 'down') {
        // Only presses within the radar's reach grab a dial.
        if (Math.hypot(x, y) > props.radius * 1.25) return
        const axis = nearestAxis(x, y)
        surface.setState({ axis, focus: axis })
        post(axis, levelAlong(axis, x, y), true)
      } else if (event.type === 'move' && state.axis !== null) {
        post(state.axis, levelAlong(state.axis, x, y))
      } else if (event.type === 'up' && state.axis !== null) {
        surface.setState({ axis: null, focus: state.focus })
      }
    })
    surface.onKey(event => {
      const state = surface.state ?? { axis: null, focus: 0 }
      const step = event.key === 'right' || event.key === 'tab' ? 1 : event.key === 'left' ? count - 1 : 0
      const focus = (state.focus + step) % count
      const level = props.levels[focus] ?? 3
      const delta = event.key === 'up' ? 1 : event.key === 'down' ? -1 : 0
      if (step === 0 && delta === 0) return
      surface.setState({ ...state, focus })
      post(focus, Math.min(5, Math.max(1, level + delta)), true)
    })
  }

  return <Box width={surface.columns} height={surface.rows} />
}

export default RadarDrag

