{
  "name": "fishstack",
  "version": "0.8.3",
  "description": "A fishStack pane for Claude Code: a perm worktree with a read-only head start, crew dials and a context library.",
  "author": {
    "name": "Patrick Lai"
  },
  "license": "MIT",
  "homepage": "https://github.com/patrick-lai/claude-fish-stack-mod",
  "repository": "https://github.com/patrick-lai/claude-fish-stack-mod",
  "types": "./types/index.d.ts",
  "userConfig": {
    "autoWorktree": {
      "type": "boolean",
      "title": "Perm worktree",
      "description": "Default for the Perm worktree toggle: give each session started in a main checkout, and each worktree Claude Code creates, a lasting slot, read-only until it is ready. Off leaves worktrees to Claude Code.",
      "default": false
    },
    "worktreeRoot": {
      "type": "string",
      "title": "Worktree root",
      "description": "Where worktree slots are kept. Empty keeps them in the repository's .claude/worktrees/fishstack/, where Claude Code enters them without asking.",
      "default": ""
    },
    "setupCommand": {
      "type": "string",
      "title": "Setup command",
      "description": "A shell command run in a new slot before the session moves in (say `pnpm install`). Empty runs nothing.",
      "default": ""
    },
    "minFreeGb": {
      "type": "number",
      "title": "Free disk to keep (GB)",
      "description": "Perm worktree stops warming new slots when less than this much disk is free, as CommissionAI does at 20 GB.",
      "default": 20
    },
    "autoAnswerMinutes": {
      "type": "number",
      "title": "Autopilot answers after (minutes)",
      "description": "With the Autonomy dial on Autopilot, a question the agent asked that nobody answers in this many minutes is answered with its recommended option (or the first).",
      "default": 15
    }
  }
}

